import { Elysia, t } from "elysia";
import { cors } from "@elysiajs/cors";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

const app = new Elysia()
  .use(cors({ origin: ["http://localhost:3000"] }))
  .get("/", () => "Welcome to Smart Repair API")
  .get("/api/tickets", () => {
    return prisma.ticket.findMany({
      orderBy: { createdAt: "desc" },
    });
  })
  .get("/api/analytics", async () => {
    const total = await prisma.ticket.count();
    const done = await prisma.ticket.count({ where: { status: "done" } });
    const urgent = await prisma.ticket.count({ where: { priority: "urgent" } });
    const inProgress = await prisma.ticket.count({ where: { status: "in-progress" } });

    const todo = total - done - inProgress;

    // 为图表提供分布数据
    const distribution = [
      { name: "待处理", value: todo, fill: "#71717a" }, // zinc-500
      { name: "维修中", value: inProgress, fill: "#3b82f6" }, // blue-500
      { name: "已完成", value: done, fill: "#22c55e" }, // green-500
    ].filter(item => item.value > 0);

    return {
      total,
      done,
      urgent,
      inProgress,
      completionRate: total === 0 ? 0 : Math.round((done / total) * 100),
      distribution
    };
  })
  .post("/api/login", async ({ body }) => {
    const { username, password } = body;
    if (username === "admin" && password === "admin123") {
      return { success: true, token: "admin-jwt-token", role: "admin", name: "Admin" };
    }
    return new Response(JSON.stringify({ error: "账号或密码错误" }), { status: 401 });
  }, {
    body: t.Object({
      username: t.String(),
      password: t.String()
    })
  })
  .post("/api/tickets", async ({ body }) => {
    const { title, description } = body;

    const urgentKeywords = ["碎", "不亮", "冒烟", "坏"];
    const isUrgent = urgentKeywords.some(keyword => description.includes(keyword));
    const priority = isUrgent ? "urgent" : "normal";

    return prisma.ticket.create({
      data: {
        title,
        description,
        priority,
        status: "todo",
      },
    });
  }, {
    body: t.Object({
      title: t.String({ minLength: 1, error: "标题不能为空" }),
      description: t.String({ minLength: 1, error: "描述不能为空" })
    })
  })
  .patch("/api/tickets/:id", async ({ params: { id }, body }) => {
    const { status } = body;
    return prisma.ticket.update({
      where: { id: Number(id) },
      data: { status },
    });
  }, {
    body: t.Object({
      status: t.String()
    })
  })
  .delete("/api/tickets/clear-done", async () => {
    return prisma.ticket.deleteMany({
      where: { status: "done" },
    });
  })
  .delete("/api/tickets/:id", async ({ params: { id } }) => {
    return prisma.ticket.delete({
      where: { id: Number(id) },
    });
  })
  .listen(8080);

console.log(
  ` Elysia is running at ${app.server?.hostname}:${app.server?.port}`
);

import { Elysia, t } from "elysia";
import { cors } from "@elysiajs/cors";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

const app = new Elysia()
  .use(cors({ origin: ["http://localhost:3000"] }))
  .get("/", () => "Welcome to Smart Repair API")
  .get("/api/tickets", () => {
    return prisma.ticket.findMany({
      orderBy: { createdAt: "desc" },
    });
  })
  .get("/api/analytics", async () => {
    const total = await prisma.ticket.count();
    const done = await prisma.ticket.count({ where: { status: "done" } });
    const urgent = await prisma.ticket.count({ where: { priority: "urgent" } });
    const inProgress = await prisma.ticket.count({ where: { status: "in-progress" } });

    const todo = total - done - inProgress;

    // 为图表提供分布数据
    const distribution = [
      { name: "待处理", value: todo, fill: "#71717a" }, // zinc-500
      { name: "维修中", value: inProgress, fill: "#3b82f6" }, // blue-500
      { name: "已完成", value: done, fill: "#22c55e" }, // green-500
    ].filter(item => item.value > 0);

    return {
      total,
      done,
      urgent,
      inProgress,
      completionRate: total === 0 ? 0 : Math.round((done / total) * 100),
      distribution
    };
  })
  .post("/api/login", async ({ body }) => {
    const { username, password } = body;
    if (username === "admin" && password === "admin123") {
      return { success: true, token: "admin-jwt-token", role: "admin", name: "Admin" };
    }
    return new Response(JSON.stringify({ error: "账号或密码错误" }), { status: 401 });
  }, {
    body: t.Object({
      username: t.String(),
      password: t.String()
    })
  })
  .post("/api/tickets", async ({ body }) => {
    const { title, description } = body;

    const urgentKeywords = ["碎", "不亮", "冒烟", "坏"];
    const isUrgent = urgentKeywords.some(keyword => description.includes(keyword));
    const priority = isUrgent ? "urgent" : "normal";

    return prisma.ticket.create({
      data: {
        title,
        description,
        priority,
        status: "todo",
      },
    });
  }, {
    body: t.Object({
      title: t.String({ minLength: 1, error: "标题不能为空" }),
      description: t.String({ minLength: 1, error: "描述不能为空" })
    })
  })
  .patch("/api/tickets/:id", async ({ headers, set, params: { id }, body }) => {
    if (headers.authorization !== "Bearer admin-jwt-token") {
      set.status = 401;
      return { error: "未授权的操作" };
    }
    const { status } = body;
    return prisma.ticket.update({
      where: { id: Number(id) },
      data: { status },
    });
  }, {
    body: t.Object({
      status: t.String()
    })
  })
  .delete("/api/tickets/clear-done", async ({ headers, set }) => {
    if (headers.authorization !== "Bearer admin-jwt-token") {
      set.status = 401;
      return { error: "未授权的操作" };
    }
    return prisma.ticket.deleteMany({
      where: { status: "done" },
    });
  })
  .delete("/api/tickets/:id", async ({ headers, set, params: { id } }) => {
    if (headers.authorization !== "Bearer admin-jwt-token") {
      set.status = 401;
      return { error: "未授权的操作" };
    }
    return prisma.ticket.delete({
      where: { id: Number(id) },
    });
  })
  .listen(8080);

console.log(
  ` Elysia is running at ${app.server?.hostname}:${app.server?.port}`
);

"use client";

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';

interface Ticket {
  id: number;
  title: string;
  description: string;
  priority: 'urgent' | 'normal';
  status: 'todo' | 'in-progress' | 'done';
  createdAt: string;
  updatedAt: string;
}

export default function SmartRepairHub() {
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [isDragging, setIsDragging] = useState(false); // 拖拽状态感知
  const [isSubmitting, setIsSubmitting] = useState(false); // 防止重复提交

  const fetchTickets = async () => {
    try {
      const response = await fetch('http://localhost:8080/api/tickets');
      if (response.ok) {
        const data = await response.json();
        setTickets(data);
      }
    } catch (error) {
      console.error('Error fetching tickets:', error);
    }
  };

  useEffect(() => {
    fetchTickets();
  }, []);

  const handleSubmit = async () => {
    if (!title.trim() || !description.trim()) return;

    setIsSubmitting(true);
    try {
      const response = await fetch('http://localhost:8080/api/tickets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, description }),
      });
      if (response.ok) {
        setTitle('');
        setDescription('');
        await fetchTickets();
      }
    } catch (error) {
      console.error('Error creating ticket:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  // 处理删除
  const handleDelete = async (e: React.MouseEvent, id: number) => {
    e.stopPropagation();
    if (!confirm('确定要删除这条报修记录吗？')) return;

    try {
      const response = await fetch(`http://localhost:8080/api/tickets/${id}`, {
        method: 'DELETE',
      });
      if (response.ok) {
        setTickets(prev => prev.filter(t => t.id !== id));
      }
    } catch (error) {
      console.error('Error deleting ticket:', error);
    }
  };

  // 处理拖拽开始
  const handleDragStart = (e: React.DragEvent, id: number) => {
    e.dataTransfer.setData('ticketId', id.toString());
    setIsDragging(true);
  };

  // 处理拖拽结束
  const handleDragEnd = () => {
    setIsDragging(false);
  };

  // 允许放置
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // 必须调用，否则不会触发 onDrop
  };

  // 处理放置
  const handleDrop = async (e: React.DragEvent, newStatus: Ticket['status']) => {
    e.preventDefault();
    setIsDragging(false);
    const ticketId = parseInt(e.dataTransfer.getData('ticketId'), 10);

    if (!ticketId) return;

    // 乐观更新 UI
    setTickets(prev =>
      prev.map(t => (t.id === ticketId ? { ...t, status: newStatus } : t))
    );

    // 发送 PATCH 请求更新后端状态
    try {
      await fetch(`http://localhost:8080/api/tickets/${ticketId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      });
    } catch (error) {
      console.error('Error updating ticket status:', error);
      // 如果失败可以考虑回滚，这里为演示简单处理重新 fetch
      await fetchTickets();
    }
  };

  const renderTickets = (status: Ticket['status']) => {
    return tickets
      .filter((ticket) => ticket.status === status)
      .map((ticket) => (
        <Card 
          key={ticket.id} 
          draggable 
          onDragStart={(e) => handleDragStart(e, ticket.id)}
          onDragEnd={handleDragEnd}
          className="bg-zinc-800 border-zinc-700 mb-4 cursor-grab active:cursor-grabbing hover:border-zinc-500 transition-colors shadow-sm group relative"
        >
          <button
            onClick={(e) => handleDelete(e, ticket.id)}
            className="absolute top-2 right-2 rounded-full p-1 opacity-0 group-hover:opacity-100 hover:bg-zinc-700 text-zinc-400 hover:text-red-400 transition-all z-10"
            title="删除工单"
          >
            ✕
          </button>

          <CardHeader className="pb-2">
            <div className="flex justify-between items-start">
              <CardTitle className="text-sm font-medium text-zinc-100 flex-1 pr-6">
                {ticket.title}
              </CardTitle>
              <Badge
                variant={ticket.priority === 'urgent' ? 'destructive' : 'default'}
                className={
                  ticket.priority === 'urgent'
                    ? 'bg-red-600 hover:bg-red-700 text-white border-transparent'
                    : 'bg-zinc-600 hover:bg-zinc-700 text-white border-transparent'
                }
              >
                {ticket.priority === 'urgent' ? '紧急' : '普通'}
              </Badge>
            </div>
          </CardHeader>
          <CardContent>
            <p className="text-xs text-zinc-400 mb-2">{ticket.description}</p>
            <p className="text-[10px] text-zinc-600">
              {new Date(ticket.createdAt).toLocaleString('zh-CN', {
                month: 'short',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
              })}
            </p>
          </CardContent>
        </Card>
      ));
  };

  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-50 p-6 font-sans">
      {/* Header */}
      <header className="flex items-center justify-between mb-8 pb-4 border-b border-zinc-800">
        <h1 className="text-2xl md:text-3xl font-extrabold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-indigo-500">
          Smart Repair Hub
        </h1>
        <div className="w-10 h-10 rounded-full bg-zinc-800 flex items-center justify-center text-zinc-400 border border-zinc-700 shadow-inner">
          <span className="text-sm font-bold">U</span>
        </div>
      </header>

      {/* Main Content gap and structure */}
      <main className="flex flex-col lg:flex-row gap-6 h-full">
        {/* Left Action Area */}
        <section className="w-full lg:w-1/4 flex flex-col gap-4">
          <div className="bg-zinc-900 rounded-xl p-6 border border-zinc-800 shadow-md">
            <h2 className="text-lg md:text-xl font-bold mb-4 text-zinc-100">AI 智能一键报修</h2>

            <div className="flex flex-col gap-4 mb-6">
              <div>
                <label className="text-xs text-zinc-400 mb-1 block">问题简述</label>
                <Input
                  placeholder="例如：实训室电脑蓝屏"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  className="bg-zinc-950 border-zinc-700 text-zinc-100"
                />
              </div>
              <div>
                <label className="text-xs text-zinc-400 mb-1 block">详细描述 (AI自动定级)</label>
                <Textarea
                  placeholder="详情描述：包含“不亮、坏、碎、冒烟”将会被AI识别为紧急故障"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="bg-zinc-950 border-zinc-700 text-zinc-100 resize-none h-24"
                />
              </div>
            </div>

            <Button
              size="lg"
              onClick={handleSubmit}
              disabled={isSubmitting || !title.trim() || !description.trim()}
              className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-semibold shadow-lg shadow-indigo-500/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSubmitting ? '正在提交...' : '立即提交报修'}
            </Button>
          </div>
        </section>

        {/* Right Kanban Area */}
        <section className="w-full lg:w-3/4 grid grid-cols-1 md:grid-cols-3 gap-6 h-full min-h-[600px] pb-10">
          {/* To Do Column */}
          <div 
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, 'todo')}
            className={`bg-zinc-900/80 rounded-xl p-4 border shadow-inner flex flex-col h-full max-h-[80vh] transition-colors ${isDragging ? 'border-zinc-700/80' : 'border-zinc-800/80'}`}
          >
            <div className="flex items-center justify-between mb-4 px-1 sticky top-0 bg-transparent z-10">
              <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wide flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-zinc-500 inline-block drop-shadow-[0_0_8px_rgba(255,255,255,0.3)]"></span>
                待处理
              </h3>
              <span className="text-xs font-medium text-zinc-500 bg-zinc-800 px-2 py-0.5 rounded-full">
                {tickets.filter(t => t.status === 'todo').length}
              </span>
            </div>
            <div className="flex flex-col flex-1 overflow-y-auto pr-1 pb-2 custom-scrollbar">{renderTickets('todo')}</div>
          </div>

          {/* In Progress Column */}
          <div 
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, 'in-progress')}
            className={`bg-zinc-900/80 rounded-xl p-4 border shadow-inner flex flex-col h-full max-h-[80vh] transition-colors ${isDragging ? 'border-blue-900/50' : 'border-zinc-800/80'}`}
          >
            <div className="flex items-center justify-between mb-4 px-1 sticky top-0 bg-transparent z-10">
              <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wide flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-blue-500 inline-block drop-shadow-[0_0_8px_rgba(59,130,246,0.8)]"></span>
                维修中
              </h3>
              <span className="text-xs font-medium text-zinc-500 bg-zinc-800 px-2 py-0.5 rounded-full">
                {tickets.filter(t => t.status === 'in-progress').length}
              </span>
            </div>
            <div className="flex flex-col flex-1 overflow-y-auto pr-1 pb-2 custom-scrollbar">{renderTickets('in-progress')}</div>
          </div>

          {/* Done Column */}
          <div 
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, 'done')}
            className={`bg-zinc-900/80 rounded-xl p-4 border shadow-inner flex flex-col h-full max-h-[80vh] transition-colors ${isDragging ? 'border-green-900/50' : 'border-zinc-800/80'}`}
          >
            <div className="flex items-center justify-between mb-4 px-1 sticky top-0 bg-transparent z-10">
              <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wide flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-green-500 inline-block drop-shadow-[0_0_8px_rgba(34,197,94,0.8)]"></span>
                已完成
              </h3>
              <span className="text-xs font-medium text-zinc-500 bg-zinc-800 px-2 py-0.5 rounded-full">
                {tickets.filter(t => t.status === 'done').length}
              </span>
            </div>
            <div className="flex flex-col flex-1 overflow-y-auto pr-1 pb-2 custom-scrollbar">{renderTickets('done')}</div>
          </div>
        </section>
      </main>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';

interface Ticket {
  id: number;
  title: string;
  description: string;
  priority: 'urgent' | 'normal';
  status: 'todo' | 'in-progress' | 'done';
  createdAt: string;
  updatedAt: string;
}

export default function SmartRepairHub() {
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [isDragging, setIsDragging] = useState(false); // 拖拽状态感知
  const [isSubmitting, setIsSubmitting] = useState(false); // 防止重复提交

  const fetchTickets = async () => {
    try {
      const response = await fetch('http://localhost:8080/api/tickets');
      if (response.ok) {
        const data = await response.json();
        setTickets(data);
      }
    } catch (error) {
      console.error('Error fetching tickets:', error);
    }
  };

  useEffect(() => {
    fetchTickets();
  }, []);

  const handleSubmit = async () => {
    if (!title.trim() || !description.trim()) return;

    setIsSubmitting(true);
    try {
      const response = await fetch('http://localhost:8080/api/tickets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, description }),
      });
      if (response.ok) {
        setTitle('');
        setDescription('');
        await fetchTickets();
      }
    } catch (error) {
      console.error('Error creating ticket:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  // 处理删除
  const handleDelete = async (e: React.MouseEvent, id: number) => {
    e.stopPropagation();
    if (!confirm('确定要删除这条报修记录吗？')) return;

    try {
      const response = await fetch(`http://localhost:8080/api/tickets/${id}`, {
        method: 'DELETE',
      });
      if (response.ok) {
        setTickets(prev => prev.filter(t => t.id !== id));
      }
    } catch (error) {
      console.error('Error deleting ticket:', error);
    }
  };

  // 处理清空已完成
  const handleClearDone = async () => {
    if (!confirm('确定要清空所有已完成的报修记录吗？')) return;

    try {
      const response = await fetch('http://localhost:8080/api/tickets/clear-done', {
        method: 'DELETE',
      });
      if (response.ok) {
        setTickets(prev => prev.filter(t => t.status !== 'done'));
      }
    } catch (error) {
      console.error('Error clearing done tickets:', error);
    }
  };

  // 处理拖拽开始
  const handleDragStart = (e: React.DragEvent, id: number) => {
    e.dataTransfer.setData('ticketId', id.toString());
    setIsDragging(true);
  };

  // 处理拖拽结束
  const handleDragEnd = () => {
    setIsDragging(false);
  };

  // 允许放置
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // 必须调用，否则不会触发 onDrop
  };

  // 处理放置
  const handleDrop = async (e: React.DragEvent, newStatus: Ticket['status']) => {
    e.preventDefault();
    setIsDragging(false);
    const ticketId = parseInt(e.dataTransfer.getData('ticketId'), 10);

    if (!ticketId) return;

    // 乐观更新 UI
    setTickets(prev =>
      prev.map(t => (t.id === ticketId ? { ...t, status: newStatus } : t))
    );

    // 发送 PATCH 请求更新后端状态
    try {
      await fetch(`http://localhost:8080/api/tickets/${ticketId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      });
    } catch (error) {
      console.error('Error updating ticket status:', error);
      // 如果失败可以考虑回滚，这里为演示简单处理重新 fetch
      await fetchTickets();
    }
  };

  const filteredTickets = tickets.filter(ticket => 
    ticket.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
    ticket.description.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const renderTickets = (status: Ticket['status']) => {
    const columnTickets = filteredTickets.filter((ticket) => ticket.status === status);

    if (columnTickets.length === 0) {
      return (
        <div className="flex flex-col items-center justify-center py-10 text-zinc-500 border-2 border-dashed border-zinc-800/50 rounded-lg mx-1 mt-2 bg-zinc-900/30">
          <span className="text-2xl mb-2 opacity-50"></span>
          <p className="text-xs font-medium">
            {searchQuery ? '未找到相关工单' : '暂无数据'}
          </p>
        </div>
      );
    }

    return columnTickets.map((ticket) => (
      <Card 
        key={ticket.id} 
        draggable 
        onDragStart={(e) => handleDragStart(e, ticket.id)}
        onDragEnd={handleDragEnd}
        className="bg-zinc-800 border-zinc-700 mb-4 cursor-grab active:cursor-grabbing hover:border-zinc-500 transition-colors shadow-sm group relative"
      >
        <button
          onClick={(e) => handleDelete(e, ticket.id)}
          className="absolute top-2 right-2 rounded-full p-1 opacity-0 group-hover:opacity-100 hover:bg-zinc-700 text-zinc-400 hover:text-red-400 transition-all z-10"
          title="删除工单"
        >
          ✕
        </button>

        <CardHeader className="pb-2">
          <div className="flex justify-between items-start">
            <CardTitle className="text-sm font-medium text-zinc-100 flex-1 pr-6">
              {ticket.title}
            </CardTitle>
            <Badge
              variant={ticket.priority === 'urgent' ? 'destructive' : 'default'}
              className={
                ticket.priority === 'urgent'
                  ? 'bg-red-600 hover:bg-red-700 text-white border-transparent'
                  : 'bg-zinc-600 hover:bg-zinc-700 text-white border-transparent'
              }
            >
              {ticket.priority === 'urgent' ? '紧急' : '普通'}
            </Badge>
          </div>
        </CardHeader>
        <CardContent>
          <p className="text-xs text-zinc-400 mb-2">{ticket.description}</p>
          <p className="text-[10px] text-zinc-600">
            {new Date(ticket.createdAt).toLocaleString('zh-CN', {
              month: 'short',
              day: 'numeric',
              hour: '2-digit',
              minute: '2-digit',
            })}
          </p>
        </CardContent>
      </Card>
    ));
  };

  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-50 p-6 font-sans">
      {/* Header */}
      <header className="flex items-center justify-between mb-8 pb-4 border-b border-zinc-800">
        <h1 className="text-2xl md:text-3xl font-extrabold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-indigo-500">
          Smart Repair Hub
        </h1>
        <div className="flex items-center gap-4">
          <div className="relative hidden sm:block">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500 text-xs"></span>
            <Input
              placeholder="搜索报修工单..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-8 bg-zinc-900 border-zinc-700 text-zinc-100 w-64 rounded-full h-9 text-xs focus-visible:ring-indigo-500"
            />
          </div>
          <div className="w-10 h-10 rounded-full bg-zinc-800 flex items-center justify-center text-zinc-400 border border-zinc-700 shadow-inner hover:bg-zinc-700 hover:text-zinc-300 transition-colors cursor-pointer">
            <span className="text-sm font-bold">U</span>
          </div>
        </div>
      </header>

      {/* Main Content gap and structure */}
      <main className="flex flex-col lg:flex-row gap-6 h-full">
        {/* Left Action Area */}
        <section className="w-full lg:w-1/4 flex flex-col gap-4">
          <div className="bg-zinc-900 rounded-xl p-6 border border-zinc-800 shadow-md">
            <h2 className="text-lg md:text-xl font-bold mb-4 text-zinc-100">AI 智能一键报修</h2>

            <div className="flex flex-col gap-4 mb-6">
              <div>
                <label className="text-xs text-zinc-400 mb-1 block">问题简述</label>
                <Input
                  placeholder="例如：实训室电脑蓝屏"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  className="bg-zinc-950 border-zinc-700 text-zinc-100"
                />
              </div>
              <div>
                <label className="text-xs text-zinc-400 mb-1 block">详细描述 (AI自动定级)</label>
                <Textarea
                  placeholder="详情描述：包含“不亮、坏、碎、冒烟”将会被AI识别为紧急故障"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="bg-zinc-950 border-zinc-700 text-zinc-100 resize-none h-24"
                />
              </div>
            </div>

            <Button
              size="lg"
              onClick={handleSubmit}
              disabled={isSubmitting || !title.trim() || !description.trim()}
              className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-semibold shadow-lg shadow-indigo-500/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isSubmitting ? '正在提交...' : '立即提交报修'}
            </Button>
          </div>
        </section>

        {/* Right Kanban Area */}
        <section className="w-full lg:w-3/4 grid grid-cols-1 md:grid-cols-3 gap-6 h-full min-h-[600px] pb-10">
          {/* To Do Column */}
          <div 
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, 'todo')}
            className={`bg-zinc-900/80 rounded-xl p-4 border shadow-inner flex flex-col h-full max-h-[80vh] transition-colors ${isDragging ? 'border-zinc-700/80' : 'border-zinc-800/80'}`}
          >
            <div className="flex items-center justify-between mb-4 px-1 sticky top-0 bg-transparent z-10">
              <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wide flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-zinc-500 inline-block drop-shadow-[0_0_8px_rgba(255,255,255,0.3)]"></span>
                待处理
              </h3>
              <span className="text-xs font-medium text-zinc-500 bg-zinc-800 px-2 py-0.5 rounded-full">
                {tickets.filter(t => t.status === 'todo').length}
              </span>
            </div>
            <div className="flex flex-col flex-1 overflow-y-auto pr-1 pb-2 custom-scrollbar">{renderTickets('todo')}</div>
          </div>

          {/* In Progress Column */}
          <div 
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, 'in-progress')}
            className={`bg-zinc-900/80 rounded-xl p-4 border shadow-inner flex flex-col h-full max-h-[80vh] transition-colors ${isDragging ? 'border-blue-900/50' : 'border-zinc-800/80'}`}
          >
            <div className="flex items-center justify-between mb-4 px-1 sticky top-0 bg-transparent z-10">
              <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wide flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-blue-500 inline-block drop-shadow-[0_0_8px_rgba(59,130,246,0.8)]"></span>
                维修中
              </h3>
              <span className="text-xs font-medium text-zinc-500 bg-zinc-800 px-2 py-0.5 rounded-full">
                {tickets.filter(t => t.status === 'in-progress').length}
              </span>
            </div>
            <div className="flex flex-col flex-1 overflow-y-auto pr-1 pb-2 custom-scrollbar">{renderTickets('in-progress')}</div>
          </div>

          {/* Done Column */}
          <div 
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, 'done')}
            className={`bg-zinc-900/80 rounded-xl p-4 border shadow-inner flex flex-col h-full max-h-[80vh] transition-colors ${isDragging ? 'border-green-900/50' : 'border-zinc-800/80'}`}
          >
            <div className="flex items-center justify-between mb-4 px-1 sticky top-0 bg-transparent z-10">
              <h3 className="text-sm font-semibold text-zinc-300 uppercase tracking-wide flex items-center gap-2">
                <span className="w-2 h-2 rounded-full bg-green-500 inline-block drop-shadow-[0_0_8px_rgba(34,197,94,0.8)]"></span>
                已完成
              </h3>
              <div className="flex items-center gap-2">
                <span className="text-xs font-medium text-zinc-500 bg-zinc-800 px-2 py-0.5 rounded-full">
                  {tickets.filter(t => t.status === 'done').length}
                </span>
                {tickets.some(t => t.status === 'done') && (
                  <button 
                    onClick={handleClearDone} 
                    className="text-xs text-zinc-500 hover:text-red-400 transition-colors p-1 hover:bg-zinc-800 rounded opacity-70 hover:opacity-100" 
                    title="清空所有已完成工单"
                  >
                    ️
                  </button>
                )}
              </div>
            </div>
            <div className="flex flex-col flex-1 overflow-y-auto pr-1 pb-2 custom-scrollbar">{renderTickets('done')}</div>
          </div>
        </section>
      </main>
    </div>
  );
}
